Exactoo. El -1 solo tiene sentido cuando ya sabemos que no está en ningún lugar. Aquí está el programa completo:

```c
#include <stdio.h>

/* Búsqueda lineal: devuelve el índice del valor buscado, o -1 si no existe */
int buscar(int arr[], int N, int valor) {
    for (int i = 0; i < N; i++) {
        if (arr[i] == valor) {
            return i; /* encontrado: retornar posición */
        }
    }
    return -1; /* centinela: no encontrado */
}

int main(void) {
    int N;
    printf("Tamaño del arreglo: ");
    scanf("%d", &N);

    int arr[N]; /* índices válidos: 0 .. N-1 */

    /* Loop: llenar el arreglo */
    for (int i = 0; i < N; i++) {
        printf("arr[%d]: ", i);
        scanf("%d", &arr[i]);
    }

    int valor;
    printf("Valor a buscar: ");
    scanf("%d", &valor);

    int pos = buscar(arr, N, valor);

    if (pos != -1) {
        printf("Encontrado en índice %d.\n", pos);
    } else {
        printf("El valor %d no está en el arreglo.\n", valor);
    }

    return 0;
}
```

La función `buscar` encapsula la lógica de búsqueda. El `return -1` al final solo se alcanza si el loop completo no encontró el valor — ese es el centinela. En `main` siempre verificamos `pos != -1` antes de usarlo como índice.
